//! 🔺️ Controlled native geometry buffers, complete PBR material fields and texture octets.
use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint3,SemioUv,SemioRgba};
use crate::standards::v1::subsets::mesh::schema::snapshot::{SemioMeshSnapshot,SemioMesh,SemioPrimitive,SemioTopology,SemioMaterial,SemioTexture,STDIO_SEMIOMESH_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(crate) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioMeshSnapshot,ValueError>{native::decode(payload,STDIO_SEMIOMESH_DOCUMENT_SCHEMA,control,binary,document)}
fn topology(tag:u8)->Result<SemioTopology,ValueError>{Ok(match tag{0=>SemioTopology::Points,1=>SemioTopology::Lines,2=>SemioTopology::LineStrip,3=>SemioTopology::Triangles,4=>SemioTopology::TriangleStrip,5=>SemioTopology::TriangleFan,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native topology"))})}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))}
fn f32(reader:&mut store::ByteReader<'_>)->Result<f32,ValueError>{Ok(f32::from_bits(reader.read_u32_le().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?))}
fn point(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,ValueError>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn rgba(reader:&mut store::ByteReader<'_>)->Result<SemioRgba,ValueError>{Ok(SemioRgba{r:f32(reader)?,g:f32(reader)?,b:f32(reader)?,a:f32(reader)?})}
fn optional_text(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>Ok(None),1=>Ok(Some(native::text(reader,control)?)),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native texture reference presence"))}}
fn optional_text_record(value:&str,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native texture reference presence"))}Ok(Some(native::hex_text(value,control)?))}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioMeshSnapshot,ValueError>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Semio mesh native format"))}let schema=native::text(&mut reader,control)?;
 let meshes=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let primitives=native::binary_list(reader,control,limits,entities,|reader,control,entities|{
 let id=native::text(reader,control)?;let topology=topology(reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?)?;let positions=native::binary_list(reader,control,limits,entities,|reader,_,_|point(reader))?;let normals=native::binary_list(reader,control,limits,entities,|reader,_,_|point(reader))?;let uvs=native::binary_list(reader,control,limits,entities,|reader,_,_|Ok(SemioUv{u:f64(reader)?,v:f64(reader)?}))?;let colors=native::binary_list(reader,control,limits,entities,|reader,_,_|rgba(reader))?;let indices=native::binary_list(reader,control,limits,entities,|reader,_,_|reader.read_u32_le().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string())))?;let material_id=match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>None,1=>Some(native::text(reader,control)?),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native material presence"))};Ok(SemioPrimitive{id,topology,positions,normals,uvs,colors,indices,material_id})})?;Ok(SemioMesh{id,primitives})})?;
 let materials=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|{let id=native::text(reader,control)?;let base_color=rgba(reader)?;let metallic=f32(reader)?;let roughness=f32(reader)?;Ok(SemioMaterial{id,base_color,metallic,roughness,base_color_texture:optional_text(reader,control)?,metallic_roughness_texture:optional_text(reader,control)?,normal_texture:optional_text(reader,control)?,occlusion_texture:optional_text(reader,control)?,emissive_texture:optional_text(reader,control)?})})?;
 let textures=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|{let id=native::text(reader,control)?;let mime=native::text(reader,control)?;let bytes=control.copy_bytes(native::bytes(reader)?)?;Ok(SemioTexture{id,mime,bytes})})?;
 if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio mesh native trailing bytes"))}Ok(SemioMeshSnapshot{schema,meshes,materials,textures})
}
fn point_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint3,ValueError>{let[x,y,z]=native::record(value,control)?;Ok(SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?})}
fn rgba_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioRgba,ValueError>{let[r,g,b,a]=native::record(value,control)?;Ok(SemioRgba{r:native::float32(r,control)?,g:native::float32(g,control)?,b:native::float32(b,control)?,a:native::float32(a,control)?})}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioMeshSnapshot,ValueError>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","meshes","materials","textures"],control)?;let schema=native::hex_text(fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Semio mesh native schema missing"))?,control)?;
 let meshes=native::text_list(fields[1].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,primitives]=native::record(value,control)?;let id=native::hex_text(id,control)?;let primitives=native::text_list(primitives,control,limits,entities,|value,control,entities|{
 let[id,topology_fields,positions,normals,uvs,colors,indices,material_fields]=native::record(value,control)?;let id=native::hex_text(id,control)?;let tag=match topology_fields{"P"=>0,"L"=>1,"S"=>2,"T"=>3,"X"=>4,"F"=>5,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native topology"))};let topology=topology(tag)?;let positions=native::text_list(positions,control,limits,entities,|value,control,_|point_text(value,control))?;let normals=native::text_list(normals,control,limits,entities,|value,control,_|point_text(value,control))?;let uvs=native::text_list(uvs,control,limits,entities,|value,control,_|{let[u,v]=native::record(value,control)?;Ok(SemioUv{u:native::float(u,control)?,v:native::float(v,control)?})})?;let colors=native::text_list(colors,control,limits,entities,|value,control,_|rgba_text(value,control))?;let indices=native::text_list(indices,control,limits,entities,|value,control,_|{control.scoped_stage(|control|{control.begin_stage(value.len())?;for _ in value.bytes(){control.step()?;}value.parse::<u32>().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native index"))})})?;let material_id=if material_fields=="[0]"{None}else{let[tag,value]=native::record(material_fields,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native material presence"))}Some(native::hex_text(value,control)?)};Ok(SemioPrimitive{id,topology,positions,normals,uvs,colors,indices,material_id})})?;Ok(SemioMesh{id,primitives})})?;
 let materials=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,color,metallic,roughness,base_color_texture,metallic_roughness_texture,normal_texture,occlusion_texture,emissive_texture]=native::record(value,control)?;Ok(SemioMaterial{id:native::hex_text(id,control)?,base_color:rgba_text(color,control)?,metallic:native::float32(metallic,control)?,roughness:native::float32(roughness,control)?,base_color_texture:optional_text_record(base_color_texture,control)?,metallic_roughness_texture:optional_text_record(metallic_roughness_texture,control)?,normal_texture:optional_text_record(normal_texture,control)?,occlusion_texture:optional_text_record(occlusion_texture,control)?,emissive_texture:optional_text_record(emissive_texture,control)? })})?;
 let textures=native::text_list(fields[3].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,mime,bytes]=native::record(value,control)?;Ok(SemioTexture{id:native::hex_text(id,control)?,mime:native::hex_text(mime,control)?,bytes:native::hex(bytes,control)?})})?;Ok(SemioMeshSnapshot{schema,meshes,materials,textures})
}
